/**
 * Test script to examine the exact content being generated by notification service
 */

import { storage } from './server/storage.js';
import { sendBookingNotificationToGroups } from './server/services/notificationGroupService.js';

async function testNotificationContent() {
  console.log("=== TESTING NOTIFICATION CONTENT GENERATION ===");
  
  try {
    // Initialize database connection
    console.log("Database connection established successfully");
    
    // Get a test booking
    const booking = await storage.getBooking(94);
    if (!booking) {
      console.error("Booking not found");
      return;
    }
    
    console.log(`Retrieved booking: ${booking.title} with notifyList:`, booking.notifyList);
    
    // Get studio information
    const studioIds = booking.notifyList || [];
    if (studioIds.length === 0) {
      console.log("No notification groups configured for this booking");
      return;
    }
    
    const studio = await storage.getStudio(studioIds[0]); // Get first studio for testing
    console.log(`Studio: ${studio?.name || 'Unknown'}`);
    
    // Get notification group
    const notificationGroup = await storage.getNotificationGroup(studioIds[0]);
    console.log(`Notification group ${studioIds[0]}: ${notificationGroup?.name} (${notificationGroup?.email})`);
    
    // Test the notification content generation by intercepting the email content
    console.log("Testing notification content generation...");
    
    // We'll mock the sendEmail function to capture the content
    const originalSendEmail = (await import('./server/services/emailService.js')).sendEmail;
    
    let capturedEmailContent = null;
    
    // Mock sendEmail to capture content
    const mockSendEmail = async (params) => {
      capturedEmailContent = params;
      console.log("=== CAPTURED EMAIL CONTENT ===");
      console.log("To:", params.to);
      console.log("From:", params.from);
      console.log("Subject:", params.subject);
      console.log("HTML Content Length:", params.html?.length || 0);
      console.log("Text Content Length:", params.text?.length || 0);
      
      if (params.html) {
        console.log("=== HTML CONTENT PREVIEW ===");
        console.log(params.html.substring(0, 500) + "...");
      }
      
      return true; // Return success without actually sending
    };
    
    // Replace the sendEmail function temporarily
    const emailService = await import('./server/services/emailService.js');
    emailService.sendEmail = mockSendEmail;
    
    // Now test the notification
    const result = await sendBookingNotificationToGroups(
      booking,
      studio,
      [studioIds[0]],
      'created',
      true
    );
    
    console.log("Notification result:", result);
    
    if (capturedEmailContent) {
      console.log("=== EMAIL CONTENT ANALYSIS ===");
      console.log("Content captured successfully");
      
      if (capturedEmailContent.html) {
        // Check for common HTML issues
        const htmlContent = capturedEmailContent.html;
        const htmlTagCount = (htmlContent.match(/<html/g) || []).length;
        const bodyTagCount = (htmlContent.match(/<body/g) || []).length;
        const doctypeCount = (htmlContent.match(/<!DOCTYPE/g) || []).length;
        
        console.log(`HTML tag count: ${htmlTagCount}`);
        console.log(`BODY tag count: ${bodyTagCount}`);
        console.log(`DOCTYPE count: ${doctypeCount}`);
        
        if (htmlTagCount > 1 || bodyTagCount > 1 || doctypeCount > 1) {
          console.log("⚠️  WARNING: Duplicate HTML structure detected - this could cause SendGrid 400 errors");
        } else {
          console.log("✓ HTML structure appears correct");
        }
      }
    } else {
      console.log("❌ No email content was captured");
    }
    
  } catch (error) {
    console.error("Error in test:", error);
  }
  
  console.log("=== TEST COMPLETED ===");
}

testNotificationContent().catch(console.error);